function escapeRegex(string) {
    return string.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
}

function inferLocationFromText(text = '') {
    const cleanText = String(text).toLowerCase();
    
    // Check specific cities first (using word boundaries)
    for (const [cityName, info] of Object.entries(CITIES)) {
        const escapedName = escapeRegex(cityName);
        const regex = new RegExp('\\b' + escapedName + '\\b', 'i');
        if (regex.test(cleanText)) {
            return {
                country: info.country,
                coordinates: info.coordinates,
                city: cityName.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')
            };
        }
    }
    
    // Check countries next (using word boundaries)
    for (const [countryName, info] of Object.entries(COUNTRIES)) {
        const escapedName = escapeRegex(countryName);
        const regex = new RegExp('\\b' + escapedName + '\\b', 'i');
        if (regex.test(cleanText)) {
            return {
                country: info.country,
                coordinates: info.coordinates
            };
        }
    }
    
    // Extra fallback for common region/continent names (using word boundaries)
    if (/\bafrica\b/i.test(cleanText)) {
        return { country: 'Africa', coordinates: [1.0287, 23.6849] };
    }
    if (/\b(americas|america)\b/i.test(cleanText)) {
        return { country: 'Americas', coordinates: [19.0000, -96.0000] };
    }
    if (/\beurope\b/i.test(cleanText)) {
        return { country: 'Europe', coordinates: [48.5260, 15.2551] };
    }
    if (/\basia\b/i.test(cleanText)) {
        return { country: 'Asia', coordinates: [34.0479, 100.6197] };
    }

    // Country aliases (short forms, nationalities, languages that don't match in COUNTRIES)
    const aliases = [
        [/\bu\.?s\.?\b|\bunited states\b|\bamerica\b|\bamerican\b/i, { country: 'United States', coordinates: [39.8283, -98.5795] }],
        [/\bu\.?k\.?\b|\bunited kingdom\b|\bbritain\b|\bengland\b|\bbritish\b/i, { country: 'United Kingdom', coordinates: [55.3781, -3.4360] }],
        [/\bu\.?a\.?e\.?\b|\bemirati/i, { country: 'United Arab Emirates', coordinates: [23.4241, 53.8478] }],
        [/\bmiddle east\b/i, { country: 'Middle East', coordinates: [29.3117, 47.4818] }],
        [/\bgaza\b/i, { country: 'Palestine', coordinates: [31.3547, 34.3088] }],
        [/\bukraine\b|\bukrainian\b/i, { country: 'Ukraine', coordinates: [48.3794, 31.1656] }],
        [/\brussia\b|\brussian\b/i, { country: 'Russia', coordinates: [61.5240, 105.3188] }],
        [/\bchina\b|\bchinese\b/i, { country: 'China', coordinates: [35.8617, 104.1954] }],
        [/\bindia\b|\bindian\b/i, { country: 'India', coordinates: [20.5937, 78.9629] }],
        [/\biran\b|\biranian\b/i, { country: 'Iran', coordinates: [32.4279, 53.6880] }],
        [/\biraq\b|\biraqi\b/i, { country: 'Iraq', coordinates: [33.2232, 43.6793] }],
        [/\bisrael\b|\bisraeli\b/i, { country: 'Israel', coordinates: [31.0461, 34.8516] }],
        [/\bsyria\b|\bsyrian\b/i, { country: 'Syria', coordinates: [34.8021, 38.9968] }],
        [/\byemen\b|\byemeni\b/i, { country: 'Yemen', coordinates: [15.5527, 48.5164] }],
        [/\bjapan\b|\bjapanese\b/i, { country: 'Japan', coordinates: [36.2048, 138.2529] }],
        [/\bgermany\b|\bgerman\b/i, { country: 'Germany', coordinates: [51.1657, 10.4515] }],
        [/\bfrance\b|\bfrench\b/i, { country: 'France', coordinates: [46.2276, 2.2137] }],
        [/\baustralia\b|\baustralian\b/i, { country: 'Australia', coordinates: [-25.2744, 133.7751] }],
        [/\bcanada\b|\bcanadian\b/i, { country: 'Canada', coordinates: [56.1304, -106.3468] }],
        [/\bbrazil\b|\bbrazilian\b/i, { country: 'Brazil', coordinates: [-14.2350, -51.9253] }],
        [/\bsouth korea\b|\bkorean\b/i, { country: 'South Korea', coordinates: [35.9078, 127.7669] }],
        [/\bnorth korea\b/i, { country: 'North Korea', coordinates: [40.3399, 127.5101] }],
        [/\btaiwan\b|\btaiwanese\b/i, { country: 'Taiwan', coordinates: [23.6978, 120.9605] }],
        [/\bturkey\b|\btürkiye\b|\bturkish\b/i, { country: 'Turkey', coordinates: [38.9637, 35.2433] }],
        [/\bvenezuela\b|\bvenezuelan\b/i, { country: 'Venezuela', coordinates: [6.4238, -66.5897] }],
        [/\bmexico\b|\bmexican\b/i, { country: 'Mexico', coordinates: [23.6345, -102.5528] }],
        [/\bsaudi arabia\b|\bsaudi\b/i, { country: 'Saudi Arabia', coordinates: [23.8859, 45.0792] }],
        [/\bqatar\b|\bqatari\b/i, { country: 'Qatar', coordinates: [25.3548, 51.1839] }],
        [/\bbahrain\b|\bbahraini\b/i, { country: 'Bahrain', coordinates: [26.0667, 50.5577] }],
        [/\buae\b/i, { country: 'United Arab Emirates', coordinates: [23.4241, 53.8478] }],
        [/\bpalestine\b|\bwest bank\b|\bpalestinian\b/i, { country: 'Palestine', coordinates: [31.9522, 35.2332] }],
        [/\blebanon\b|\blebanese\b/i, { country: 'Lebanon', coordinates: [33.8547, 35.8623] }],
        [/\bjordan\b|\bjordanian\b/i, { country: 'Jordan', coordinates: [30.5852, 36.2384] }],
        [/\begypt\b|\begyptian\b/i, { country: 'Egypt', coordinates: [26.8206, 30.8025] }],
        [/\bnigeria\b|\bnigerian\b/i, { country: 'Nigeria', coordinates: [9.0820, 8.6753] }],
        [/\bsomalia\b|\bsomali\b/i, { country: 'Somalia', coordinates: [5.1521, 46.1996] }],
        [/\bsudan\b|\bsudanese\b/i, { country: 'Sudan', coordinates: [12.8628, 30.2174] }],
    ];
    for (const [pattern, loc] of aliases) {
        if (pattern.test(cleanText)) return loc;
    }

    // Default fallback
    return {
        country: 'Global',
        coordinates: [20, 0]
    };
}

module.exports = {
    inferLocationFromText,
    CITIES,
    COUNTRIES
};
